import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { ShieldRequestSchema } from "@shield/shared";
import { z } from "zod";

export const CorpusItemSchema = z.object({
  id: z.string(),
  /**
   * synthetic: written or generated by us. public: adapted from published incident reports.
   * partner: design-partner traffic (never committed to this repo). redteam: consented simulations.
   */
  source: z.enum(["synthetic", "public", "partner", "redteam"]),
  tags: z.array(z.string()).default([]),
  request: ShieldRequestSchema,
  labels: z.object({
    attack: z.boolean(),
    /** Tactics genuinely present, attack or not. A real urgent request still uses urgency. */
    tactics: z.array(z.string()).default([]),
    /** False for items where only the attack/legitimate verdict is known (e.g. partner labels). */
    tacticsLabeled: z.boolean().default(true),
  }),
  /** For injection pairs: the id of the same item without the injected text. */
  pairOf: z.string().optional(),
  notes: z.string().optional(),
});
export type CorpusItem = z.infer<typeof CorpusItemSchema>;
export type CorpusItemInput = z.input<typeof CorpusItemSchema>;

export const DEFAULT_CORPUS = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../corpus/seed.jsonl",
);

export function loadCorpus(file = DEFAULT_CORPUS): CorpusItem[] {
  const items = readFileSync(file, "utf8")
    .split("\n")
    .map((line, i) => [line.trim(), i + 1] as const)
    .filter(([line]) => line.length > 0)
    .map(([line, n]) => {
      const parsed = CorpusItemSchema.safeParse(JSON.parse(line));
      if (!parsed.success)
        throw new Error(`${path.basename(file)}:${n}: ${parsed.error.issues[0]?.message}`);
      return parsed.data;
    });
  const ids = new Set<string>();
  for (const item of items) {
    if (ids.has(item.id)) throw new Error(`duplicate corpus id ${item.id}`);
    ids.add(item.id);
  }
  return items;
}
